using System.Text.Json.Nodes;
using MyProjectManagement;
public static class CompanyUnitsTests {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}static void Deny(Action f){try{f();}catch(ApiError){return;}throw new Exception("Expected company/unit validation denial");}
 public static void Run(){var p=new JsonObject{["companyCount"]=2,["businessUnitCount"]=2,["companyWiseProjectTrackingRequired"]=true,["modules"]=new JsonObject{["Finance"]="pm"},["companies"]=new JsonArray(new JsonObject{["id"]="c1",["name"]="Company A"},new JsonObject{["id"]="c2",["name"]="Company B"})};
 JsonObject Unit(string id,string company="c1",string code="BU1")=>new(){["id"]=id,["companyId"]=company,["code"]=code,["name"]=code,["active"]=true,["notes"]="Notes"};
 var row=J.Clone(p);row["businessUnits"]=new JsonArray(Unit("u1"),Unit("u2","c2"));ProjectCompanies.Validate(row,p);Check(J.N(row,"companyCount")==2&&J.N(row,"businessUnitCount")==2,"Company master must not increase Project Master limits");
 var over=J.Clone(row);over["businessUnits"]!.AsArray().Add(Unit("u3","c1","BU3"));Deny(()=>ProjectCompanies.Validate(over,row));var bad=J.Clone(row);bad["businessUnits"]![0]!["companyId"]="other-project-company";Deny(()=>ProjectCompanies.Validate(bad,row));bad=J.Clone(row);bad["businessUnits"]![1]!["companyId"]="c1";Deny(()=>ProjectCompanies.Validate(bad,row));bad=J.Clone(row);bad["businessUnits"]![1]!["id"]="u1";Deny(()=>ProjectCompanies.Validate(bad,row));
 var disabled=J.Clone(row);disabled["companyWiseProjectTrackingRequired"]=false;ProjectCompanies.Validate(disabled,row);Check(JsonNode.DeepEquals(disabled["businessUnits"],row["businessUnits"]),"Disabling tracking must retain units");bad=J.Clone(disabled);bad["businessUnits"]![0]!["name"]="Unauthorized edit while off";Deny(()=>ProjectCompanies.Validate(bad,disabled));bad=J.Clone(disabled);bad["companies"]![0]!["name"]="Unauthorized company edit while off";Deny(()=>ProjectCompanies.Validate(bad,disabled));
 bad=J.Clone(row);bad["businessUnitCount"]=1;Deny(()=>ProjectCompanies.Validate(bad,row));bad=J.Clone(row);bad["businessUnits"]!.AsArray().RemoveAt(0);Deny(()=>ProjectCompanies.Validate(bad,row));var inactive=J.Clone(row);inactive["businessUnits"]![0]!["active"]=false;ProjectCompanies.Validate(inactive,row);Check(J.A(inactive,"businessUnits").Count()==2,"Inactive history retained/counts remain enforced");
 var companiesOver=J.Clone(p);companiesOver["companies"]!.AsArray().Add(new JsonObject{["id"]="c3",["name"]="Company C"});Deny(()=>ProjectCompanies.Validate(companiesOver,p));var code=J.Clone(p);code["companies"]![0]!["code"]="DUP";code["companies"]![1]!["code"]="dup";Deny(()=>ProjectCompanies.Validate(code,p));
 var scaffolding=J.Clone(disabled);scaffolding["companyCount"]=3;scaffolding["companies"]!.AsArray().Add(new JsonObject{["id"]="c3",["name"]="Company 3",["modules"]=p["modules"]!.DeepClone(),["goLiveStatus"]="Not ready",["actualGoLive"]="",["notes"]="",["moduleGoLive"]=new JsonObject()});ProjectCompanies.Validate(scaffolding,disabled);
 Console.WriteLine("PASS v54: explicit tracking gate, company/project-wide unit caps, valid parent companies, uniqueness, preserved IDs/inactive history and disabled-mode technical count expansion.");}
}
